HEADER = struct.Struct('>4sBBHII')
MAGIC, VERSION = b'C22E', 1
OBSERVE, END, RESULT, ENDED = 1, 2, 129, 130
MAX_METADATA = 2048
MAX_REQUEST = 16384
MAX_REPLY_PAYLOAD = 4096  # including the core's original LF
MAX_RESPONSE = 6160
MAX_FRAME_INDEX = 65536
MAX_INVOCATION = (1 << 63) - 1
